"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { Loader2, Settings, Save, PanelBottom, FileText, Globe } from "lucide-react";
import { useAuthStore } from "@/store/auth-store";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { FooterContentEditor } from "@/components/admin/footer-content-editor";
import { PageContentEditor } from "@/components/admin/page-content-editor";

interface SiteSettings {
  siteName: string;
  siteDescription: string;
  contactPhone: string;
  contactEmail: string;
  address: string;
  maintenanceMode: boolean;
  allowRegistration: boolean;
  emailNotifications: boolean;
  lowStockThreshold: number;
  itemsPerPage: number;
}

export default function AdminSettingsPage() {
  const { user, isAuthenticated } = useAuthStore();
  const { toast } = useToast();
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [activeTab, setActiveTab] = useState("general");
  const [settings, setSettings] = useState<SiteSettings>({
    siteName: "",
    siteDescription: "",
    contactPhone: "",
    contactEmail: "",
    address: "",
    maintenanceMode: false,
    allowRegistration: true,
    emailNotifications: true,
    lowStockThreshold: 10,
    itemsPerPage: 10,
  });

  useEffect(() => {
    if (!isAuthenticated || user?.role !== "admin") {
      return;
    }
    loadSettings();
  }, [isAuthenticated, user]);

  const loadSettings = async () => {
    setIsLoading(true);
    try {
      // Load from localStorage or API
      const savedSettings = localStorage.getItem("admin_site_settings");
      if (savedSettings) {
        const parsed = JSON.parse(savedSettings);
        setSettings(prev => ({ ...prev, ...parsed }));
      }
    } catch (error: any) {
      console.error("Error loading settings:", error);
      toast({
        title: "خطا",
        description: "خطا در بارگذاری تنظیمات",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    try {
      // TODO: Save settings to API
      // For now, save to localStorage
      localStorage.setItem("admin_site_settings", JSON.stringify(settings));
      
      toast({
        title: "موفق",
        description: "تنظیمات با موفقیت ذخیره شد",
      });
    } catch (error: any) {
      toast({
        title: "خطا",
        description: error.message || "خطا در ذخیره تنظیمات",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  if (!isAuthenticated || user?.role !== "admin") {
    return (
      <div className="container mx-auto px-4 py-12">
        <Card>
          <CardContent className="pt-6">
            <p className="text-center text-muted-foreground">
              دسترسی غیرمجاز
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-12">
        <div className="flex items-center justify-center min-h-[400px]">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-6 max-w-6xl">
      <div className="mb-6">
        <h1 className="text-3xl font-bold flex items-center gap-3">
          <Settings className="h-8 w-8" />
          تنظیمات سایت
        </h1>
        <p className="text-muted-foreground mt-2">
          مدیریت تنظیمات عمومی سایت، فوتر و محتوای صفحات
        </p>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-6">
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="general" className="flex items-center gap-2">
            <Globe className="h-4 w-4" />
            تنظیمات عمومی
          </TabsTrigger>
          <TabsTrigger value="footer" className="flex items-center gap-2">
            <PanelBottom className="h-4 w-4" />
            فوتر
          </TabsTrigger>
          <TabsTrigger value="pages" className="flex items-center gap-2">
            <FileText className="h-4 w-4" />
            محتوای صفحات
          </TabsTrigger>
        </TabsList>

        {/* تنظیمات عمومی */}
        <TabsContent value="general" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>تنظیمات عمومی سایت</CardTitle>
              <CardDescription>
                تنظیمات اصلی و عمومی سایت
              </CardDescription>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSave} className="space-y-6">
                <div className="space-y-2">
                  <Label htmlFor="siteName">
                    نام سایت <span className="text-destructive">*</span>
                  </Label>
                  <Input
                    id="siteName"
                    placeholder="نام سایت را وارد کنید"
                    value={settings.siteName}
                    onChange={(e) => setSettings({ ...settings, siteName: e.target.value })}
                    disabled={isSaving}
                    required
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="siteDescription">توضیحات سایت</Label>
                  <Textarea
                    id="siteDescription"
                    placeholder="توضیحات سایت را وارد کنید"
                    value={settings.siteDescription}
                    onChange={(e) => setSettings({ ...settings, siteDescription: e.target.value })}
                    disabled={isSaving}
                    rows={4}
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="contactPhone">
                      شماره تماس <span className="text-destructive">*</span>
                    </Label>
                    <Input
                      id="contactPhone"
                      type="tel"
                      placeholder="09123456789"
                      value={settings.contactPhone}
                      onChange={(e) => setSettings({ ...settings, contactPhone: e.target.value })}
                      disabled={isSaving}
                      required
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="contactEmail">
                      ایمیل تماس <span className="text-destructive">*</span>
                    </Label>
                    <Input
                      id="contactEmail"
                      type="email"
                      placeholder="info@example.com"
                      value={settings.contactEmail}
                      onChange={(e) => setSettings({ ...settings, contactEmail: e.target.value })}
                      disabled={isSaving}
                      required
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="address">آدرس</Label>
                  <Textarea
                    id="address"
                    placeholder="آدرس را وارد کنید"
                    value={settings.address}
                    onChange={(e) => setSettings({ ...settings, address: e.target.value })}
                    disabled={isSaving}
                    rows={3}
                  />
                </div>

                <div className="space-y-4 pt-4 border-t">
                  <h3 className="font-semibold">تنظیمات پیشرفته</h3>
                  
                  <div className="flex items-center justify-between">
                    <div className="space-y-0.5">
                      <Label htmlFor="maintenanceMode">حالت تعمیرات</Label>
                      <p className="text-sm text-muted-foreground">
                        در حالت تعمیرات، سایت برای کاربران عادی غیرفعال می‌شود
                      </p>
                    </div>
                    <Switch
                      id="maintenanceMode"
                      checked={settings.maintenanceMode}
                      onCheckedChange={(checked) => setSettings({ ...settings, maintenanceMode: checked })}
                      disabled={isSaving}
                    />
                  </div>

                  <div className="flex items-center justify-between">
                    <div className="space-y-0.5">
                      <Label htmlFor="allowRegistration">اجازه ثبت‌نام</Label>
                      <p className="text-sm text-muted-foreground">
                        اجازه ثبت‌نام کاربران جدید
                      </p>
                    </div>
                    <Switch
                      id="allowRegistration"
                      checked={settings.allowRegistration}
                      onCheckedChange={(checked) => setSettings({ ...settings, allowRegistration: checked })}
                      disabled={isSaving}
                    />
                  </div>

                  <div className="flex items-center justify-between">
                    <div className="space-y-0.5">
                      <Label htmlFor="emailNotifications">اعلان‌های ایمیل</Label>
                      <p className="text-sm text-muted-foreground">
                        ارسال اعلان‌ها از طریق ایمیل
                      </p>
                    </div>
                    <Switch
                      id="emailNotifications"
                      checked={settings.emailNotifications}
                      onCheckedChange={(checked) => setSettings({ ...settings, emailNotifications: checked })}
                      disabled={isSaving}
                    />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="lowStockThreshold">حد آستانه موجودی کم</Label>
                      <Input
                        id="lowStockThreshold"
                        type="number"
                        min="0"
                        value={settings.lowStockThreshold}
                        onChange={(e) => setSettings({ ...settings, lowStockThreshold: parseInt(e.target.value) || 0 })}
                        disabled={isSaving}
                      />
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="itemsPerPage">تعداد آیتم در هر صفحه</Label>
                      <Input
                        id="itemsPerPage"
                        type="number"
                        min="1"
                        value={settings.itemsPerPage}
                        onChange={(e) => setSettings({ ...settings, itemsPerPage: parseInt(e.target.value) || 10 })}
                        disabled={isSaving}
                      />
                    </div>
                  </div>
                </div>

                <div className="flex gap-2 pt-4">
                  <Button
                    type="submit"
                    className="flex-1"
                    disabled={isSaving}
                  >
                    {isSaving ? (
                      <>
                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                        در حال ذخیره...
                      </>
                    ) : (
                      <>
                        <Save className="mr-2 h-4 w-4" />
                        ذخیره تنظیمات
                      </>
                    )}
                  </Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </TabsContent>

        {/* تنظیمات فوتر */}
        <TabsContent value="footer">
          <Card>
            <CardHeader>
              <CardTitle>تنظیمات فوتر</CardTitle>
              <CardDescription>
                مدیریت محتوای فوتر سایت
              </CardDescription>
            </CardHeader>
            <CardContent>
              <FooterContentEditor />
            </CardContent>
          </Card>
        </TabsContent>

        {/* محتوای صفحات */}
        <TabsContent value="pages">
          <Card>
            <CardHeader>
              <CardTitle>محتوای صفحات</CardTitle>
              <CardDescription>
                ویرایش محتوای صفحات مختلف سایت
              </CardDescription>
            </CardHeader>
            <CardContent>
              <PageContentEditor />
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}
